from journal.features.workers.support.plan_approval import PlanApproval
from journal.support.option import USER, Option
from journal.support.option_scope import OptionScope


MERGER_TESTING = "Hand the tests over"
WORKER_TESTING = "Run the tests it wrote"
TEST_BUDGET = "Test budget"


class WorkersOptions:
    TIMEOUT = Option("workers.timeout_minutes", "Time limit of a worker run", "Minutes a worker may run before it is stopped and its report says so; 0 sets no limit", 60, unit="min")
    MODE = Option("workers.mode", "Work mode", "Builder: the agent builds it itself and sends workers when a job is better done beside it. Orchestrator: it plans, hands the work to workers, then reviews and merges it. Solo: it does everything itself, with no workers", "builder", kind="choice", choices=("builder", "orchestrator", "solo"), scope=OptionScope.PERSON, setter=USER)
    ORCHESTRATOR_WRITES_PLANS = Option("workers.orchestrator_writes_plans", "Orchestrator may write plans", "On: in orchestrator mode the orchestrator drafts plans with journal plan create. Off: only you write a plan", True, kind="switch", scope=OptionScope.PERSON, setter=USER)
    ORCHESTRATOR_RELEASES = Option("workers.orchestrator_releases", "Orchestrator may release", "On: in orchestrator mode the orchestrator may tag a version and publish a release. Off: a git tag or gh release line waits for you", False, kind="switch", scope=OptionScope.PERSON, setter=USER)
    ORCHESTRATOR_APPROVES_PLANS = Option("workers.orchestrator_approves_plans", "Orchestrator approves plans", "On: in orchestrator mode the orchestrator approves a plan itself with journal plan approve, as Plans the orchestrator may approve says. Off: only you approve a plan", False, kind="switch", scope=OptionScope.PERSON, setter=USER)
    ORCHESTRATOR_PLAN_APPROVAL = Option("workers.orchestrator_plan_approval", "Plans the orchestrator may approve", "With Orchestrator approves plans on, the plans it may approve itself: only the plans it created, the plans you created, or all of them; you approve the rest", PlanApproval.OWN.value, kind="choice", choices=tuple(approval.value for approval in PlanApproval), scope=OptionScope.PERSON, setter=USER)
    BUILDER_HANDOVER_LIMIT = Option("workers.builder_handovers", "Builder: remind after handovers in a row", "Handovers to workers with no code edit of the builder's own between them, after which it is reminded to take the next task itself; 0 never reminds", 2, unit="handovers")
    ORCHESTRATOR_LINE_LIMIT = Option("workers.orchestrator_lines", "Orchestrator: remind after lines of its own code", "Lines of code the orchestrator changes itself since its last handover, after which it is reminded to hand the work to a worker; 0 never reminds", 200, unit="lines")
    PLAN_STALL_MINUTES = Option("workers.plan_stall_minutes", "Orchestrator: started plan stalled after", "Minutes a started plan may go without progress while another started plan moves, after which the orchestrator is told so once; 0 never tells", 60, unit="min")
    FITNESS_THRESHOLD = Option("workers.fitness_threshold", "Lowest fitness before the measures off the ideal are listed", "The fitness score, from 0 to 100, against the ideal agent of its work mode, below which the agent sees its score and the measures furthest off the ideal; 0 turns this off", 70, unit="points")
    SOLO_DISPATCH_LIMIT = Option("workers.solo_dispatches", "Solo: remind after subagents over its own research", "Subagent dispatches beyond the solo agent's own reads and searches, among its last 50 tool uses, after which it is reminded to research itself; 0 never reminds", 3, unit="dispatches")
    CHECK_REMINDER_USES = Option("workers.check_reminder_uses", "Name work to check every", "Tool uses between the reminders, while the agent works on, of a worker's work that waits to be checked and merged", 25, unit="tool uses")
    TESTING = Option("workers.testing", "How workers test", "Hand the tests over: a worker never runs a test or the suite, each proof names the test and the command that runs it, and the agent that merges runs them. Run the tests it wrote: a worker runs the tests it wrote, by name, never the full suite. Test budget: a worker tests only through journal tests turn, which gives its runs a turn within the budget below; a worker whose program has hooks has any other test run refused with that line, and a worker whose program has none is given the line alone", MERGER_TESTING, kind="choice", choices=(MERGER_TESTING, WORKER_TESTING, TEST_BUDGET))
    TEST_RUNS = Option("workers.test_runs", "Test runs at once", "With the test budget, the most test runs going at a time across all workers; a worker's run waits for its turn", 3, unit="runs")
    TEST_WAITING = Option("workers.test_waiting", "Turns that may wait", "With the test budget, the most turns that may wait for a free run; blank is no limit", "", kind="text", unit="turns")
    TESTS_PER_RUN = Option("workers.tests_per_run", "Test ids in one run", "With the test budget, the most test ids one run may name", 20, unit="ids")
    TEST_RUN_MINUTES = Option("workers.test_run_minutes", "Minutes a test run may take", "With the test budget, the minutes after which a run is stopped", 10, unit="min")
    TEST_COMMAND = Option("workers.test_command", "Test command", "With the test budget, the command a turn runs with the test ids the worker names; blank runs pytest where the project has a tests folder, and where it has none a turn is refused", "", kind="text")
    FAILING_RUNS = Option("workers.failing_runs", "Failing runs in a row", "With the test budget, the failing runs in a row of one worker after which the agent that sent it is told, once, until a passed run starts the count again", 3, unit="runs")
    TEST_RUN_LINES = Option("workers.test_run_lines", "Line for each failed test run", "With the test budget, the agent that sent a worker is told in one line of each of its test runs that failed, and how many failed; off, it is told only once a worker keeps failing", True, kind="switch")
    LOAD_WINDOW = Option("workers.load_window_minutes", "Load: minutes measured over", "In orchestrator mode, the sliding window the arrivals, the clearings and the wait from arrival to clearing are measured over", 30, unit="min")
    LOAD_HALF_LIFE = Option("workers.load_half_life_minutes", "Load: half-life of the smoothing", "The minutes after which a measure of the load weighs half as much in the smoothed load", 10, unit="min")
    LOAD_WARN = Option("workers.load_warn", "Load: warn at", "The load, arrivals over clearings, at which the orchestrator is told in one line what waits and what to clear first", 0.7, unit="ratio")
    LOAD_CRITICAL = Option("workers.load_critical", "Load: critical at", "The load at which the orchestrator is told it is critical and the ways to ease it", 0.9, unit="ratio")
    SCALE_UP_AT = Option("workers.scale_up_at", "Load: add a place over", "The load that, held for the minutes below, opens one more place for a worker and a subagent, up to the ceiling", 0.8, unit="ratio")
    SCALE_DOWN_AT = Option("workers.scale_down_at", "Load: remove a place under", "The load that, held for the minutes below, closes a place, down to the floor, never while a worker holds a task or anything waits", 0.5, unit="ratio")
    SCALE_UP_DWELL = Option("workers.scale_up_dwell_minutes", "Load: minutes over before a place opens", "How long the load stays over the level above before a place opens, and between two openings", 10, unit="min")
    SCALE_DOWN_DWELL = Option("workers.scale_down_dwell_minutes", "Load: minutes under before a place closes", "How long the load stays under the level above before a place closes, and between two closings", 20, unit="min")
    PLACE_FLOOR = Option("workers.place_floor", "Load: fewest worker places", "The fewest workers out at once the load may bring the limit down to; blank, the load never changes the places", "", kind="text", unit="places", setter=USER)
    PLACE_CEILING = Option("workers.place_ceiling", "Load: most worker places", "The most workers out at once the load may bring the limit up to; blank, the load never changes the places", "", kind="text", unit="places", setter=USER)
    WEIGHT_USER_MESSAGE = Option("workers.weight_user_message", "Load: weight of a user message", "How much a message of the user's weighs in the load, a clock-out weighing 1", 3, unit="factor")
    WEIGHT_REPEAT_SEND_BACK = Option("workers.weight_repeat_send_back", "Load: weight of a clock-out after a send-back", "How much a worker coming back after it was sent back weighs in the load", 1.5, unit="factor")
    WEIGHT_IDLE_PLACE = Option("workers.weight_idle_place", "Load: weight of an idle place", "How much an idle worker weighs in the load while a task is open", 0.5, unit="factor")
    RECOVERY_FULL = Option("workers.recovery_full_score_minutes", "Fitness: minutes over the load at full score", "Minutes the load may stay over the add-a-place level with the fitness still whole", 10, unit="min")
    RECOVERY_ZERO = Option("workers.recovery_zero_score_minutes", "Fitness: minutes over the load at no score", "Minutes over the add-a-place level at which that part of the fitness scores nothing", 60, unit="min")
    INTERRUPTION_WINDOW = Option("workers.interruption_window_minutes", "Fitness: minutes the worker reports are counted over", "The window over which the reports workers file to their dispatcher are counted against the work that was open for them", 60, unit="min")
    INTERRUPTIONS_FULL = Option("workers.interruptions_full_score_per_hour", "Fitness: worker reports an hour at full score", "Reports an hour, filed while plenty of work was open, that the fitness takes with no loss", 2, unit="reports an hour")
    INTERRUPTIONS_ZERO = Option("workers.interruptions_zero_score_per_hour", "Fitness: worker reports an hour at no score", "Reports an hour, filed while plenty of work was open, at which that part of the fitness scores nothing", 8, unit="reports an hour")
    PLENTY_OPEN = Option("workers.plenty_open_tasks", "Fitness: open tasks that are plenty of work", "Tasks open for workers at a report from which the report counts as an interruption: with fewer, a worker that reports had little else to take", 3, unit="tasks")
    QUICK_REPORT_MINUTES = Option("workers.quick_report_minutes", "Fitness: minutes after its job's start a report is quick", "A worker that reports within these minutes of its job's start while plenty of work is open costs the dispatcher a drop at once, whole within the first minute and falling to half at these minutes", 3, unit="min")
    QUICK_REPORT_DROP = Option("workers.quick_report_drop_points", "Fitness: points a quick report costs", "The points a quick report takes off the fitness at once", 20, unit="points")
    TINY_JOB_DROP = Option("workers.tiny_job_drop_points", "Fitness: points a job too small for a worker costs", "A worker that reports within a minute of its job's start while no other task is open did a job its dispatcher should have done itself, which takes these points off the fitness at once", 30, unit="points")
    DROP_RECOVERY_MINUTES = Option("workers.drop_recovery_minutes", "Fitness: minutes a drop takes to recover", "Minutes over which a quick report's drop wears off, falling straight to nothing", 30, unit="min")
    SMALL_TASK_POINTS = Option("workers.small_task_points", "Fitness: points of a small task", "A task whose brief has at most this many points is small: several small tasks to one worker fit --report queue", 2, unit="points")
    LARGE_TASK_POINTS = Option("workers.large_task_points", "Fitness: points of a large task", "A task whose brief has at least this many points is large: a long queue of large tasks fits --report every <n>", 5, unit="points")
    LONG_QUEUE_TASKS = Option("workers.long_queue_tasks", "Fitness: tasks in a long queue", "A worker with at least this many tasks given to it has a long queue", 4, unit="tasks")
    MISFIT_DROP = Option("workers.report_misfit_drop_points", "Fitness: points a report choice far off costs", "The points a report choice that does not fit the work given takes off the fitness at once", 10, unit="points")
    QUEUE_WINDOW = Option("workers.queue_window_minutes", "Fitness: minutes a worker's merges are counted over", "In orchestrator mode, the window over which each worker's merges give how fast its queue drains", 60, unit="min")
    QUEUE_DRAIN_HOURS = Option("workers.queue_drain_hours", "Fitness: hours of work a queue may hold", "In orchestrator mode, a worker whose queue holds more tasks than it drains in these hours is piling up", 2, unit="hours")
    COSTLY_SHAPED_WORK = Option("workers.costly_shaped_work_dollars", "Spend on the strongest model for settled work", "In orchestrator mode, the dollars a worker on the strongest model may spend on work its profile gives a cheaper model before the orchestrator is told, once, that a cheaper model may do it", 2.0, unit="dollars")
    HELD_STILL_MINUTES = Option("workers.held_still_minutes", "Minutes blocked work may stand still", "In orchestrator mode, the minutes a blocked or paused task may go without a change before the orchestrator is told the plan needs restructuring", 60, unit="min")
    HELD_SHARE = Option("workers.held_share", "Share of tasks blocked or paused", "In orchestrator mode, the share of the tasks not done that may be blocked or paused before the orchestrator is told the plan needs restructuring", 0.4, unit="ratio")
    UNORDERED_PLAN_TASKS = Option("workers.unordered_plan_tasks", "Open tasks of a plan with no dependencies", "In orchestrator mode, the open tasks of a started plan, none of them blocked on another, at which the orchestrator is asked which depend on which; 0 never asks", 10, unit="tasks")
    PRIORITIES_MINUTES = Option("workers.priorities_minutes", "Minutes between priority checks", "In orchestrator mode, the minutes after the orchestrator last gave a started plan's priorities before it is asked again which open task unblocks the most; a new phase asks at once; 0 asks only at a phase start", 45, unit="min")
    MODEL_FIT_SAMPLE = Option("workers.model_fit_sample", "Model fit: one merge in", "In orchestrator mode, one merge in this many is sampled by a verifier on the fast model, which judges whether the worker's model was too strong, right or too weak; 0 samples none", 5, unit="merges")
    WORKER_LIMIT = Option("workers.most_out", "Workers out at once", "The most workers out at a time; a dispatch past it is refused until one reports. 0 is no limit", 3, unit="workers")
    SUBAGENT_LIMIT = Option("workers.most_subagents", "Subagents running at once", "The most subagents running at a time; one more is held until one finishes. 0 is no limit", 5, unit="subagents")
    IDLE_HOURS = Option("workers.idle_hours", "Retire a resting worker after", "A worker with nothing out, nothing to check and nothing unmerged is retired after this many hours at rest, and its worktree removed, its last commit kept; 0 never retires one", 4, unit="hours")
    MERGE_WINDOW_SECONDS = Option("workers.merge_window_seconds", "A plugin may hold a merge for", "Seconds a plugin that holds a worker's merge, such as a judge of the whole tree, may take to answer; its own window in its manifest is cut to this, and the wait in the queue below is not counted", 180, unit="seconds")
    MERGE_LIMIT = Option("workers.merge_limit", "Merges asked about at once", "The most worker merges plugins are asked about at a time; a further merge waits until one is answered; 0 for no limit", 2, unit="merges")
    PROFILE_LIMIT = Option("workers.idle_kept", "Workers kept for reuse per profile", "The most workers of one profile kept out or idle for reuse; past it a dispatch of that profile is refused while one of them is idle, so the job goes to that one. Reviewers always start fresh. 0 is no limit", 8, unit="workers")
    WORKTREE_STEP = Option("workers.worktree_step", "Make worker worktrees the journal's way", "The journal makes a worker's worktree, a worktree of each inner repository it needs and its library folders; off, your own commands below make them, told where in JOURNAL_WORKTREE and on which branch in JOURNAL_BRANCH", True, kind="switch", scope=OptionScope.MACHINE)
    PREPARATION_COMMANDS = Option("workers.preparation_commands", "Commands before a worker's worktree is made", "Your own shell commands, one per line, run in the project folder just before a worker's worktree is made; each is told JOURNAL_WORKTREE, JOURNAL_BRANCH, JOURNAL_PROJECT, JOURNAL_REPOSITORIES, JOURNAL_LIBRARIES and JOURNAL_COPIES", [], kind="lines", scope=OptionScope.MACHINE)
    BUILT_PATHS = Option("workers.built_paths", "Folders built from the sources", "Folders, one per line, that a build makes from the sources, such as a built viewer; a worker's merge that clashes only in them takes the project's side and builds them again with the command below", [], kind="lines")
    BUILD_COMMAND = Option("workers.build_command", "Command that builds them", "The shell command, run in the worker's worktree, that builds the folders above again after a merge clashed only in them", "", kind="text")
    POOL_SLOTS = Option("workers.pool_slots", "Worker slots given to the team's pool", "How many workers this machine runs at once for teammates who dispatch to the team's pool; 0 gives none", 0, unit="workers", scope=OptionScope.MACHINE, setter=USER)
    POOL_MINUTES = Option("workers.pool_daily_minutes", "Minutes a day of pool work on this machine", "How many minutes a day this machine runs workers for teammates, counted from midnight; past it a pool worker is turned down until the next day. 0 sets no limit", 0, unit="min", scope=OptionScope.MACHINE, setter=USER)
    REVIEWER_MODEL = Option("workers.reviewer_model", "Model a reviewer runs on", "The model the journal's reviewers run on, in orchestrator mode with the reviewer on; their job is bounded, comparing the brief, the proofs and the test output point by point, so the fast model does it", "haiku", kind="text")
    POOL_PROFILES = Option("workers.pool_profiles", "Profiles a pool worker may use", "The worker profiles, one per line, a teammate may dispatch to the team's pool; a pool request naming another is refused", ["journal-medior"], kind="lines", setter=USER)
    COMPLETION_COMMANDS = Option("workers.completion_commands", "Commands after a worker's worktree is made", "Your own shell commands, one per line, run inside a worker's worktree once it is made, such as installing its dependencies; told the same as the commands before", [], kind="lines", scope=OptionScope.MACHINE)
